SELECT ~ transform(array(0), e -> e)[0];

-- @compose ~ slot=0 form=column
SELECT ~ x FROM VALUES (0), (NULL) AS t(x);

-- @compose ~ slot=0 form=column_coalesce
SELECT ~ coalesce(x, x) FROM VALUES (0), (NULL) AS t(x);

-- @compose ~ slot=0 form=column_case
SELECT ~ CASE WHEN x IS NULL THEN x ELSE x END FROM VALUES (0), (NULL) AS t(x);
